t('Bot: deterministisch, Invarianten, meetingfan schwächer als gut', () => {
  const bot = require('../tools/bot.js');
  const play = (seed, P) => { const S = sim.newGame(seed); let g = 0; while (S.phase !== 'ende' && g++ < 40) bot.playDay(S, P); return S; };
  assert.deepStrictEqual(JSON.stringify(play(77, bot.POL.gut)), JSON.stringify(play(77, bot.POL.gut)));
  for (let i = 0; i < 40; i++) { const S = play(1000 + i * 31, bot.POL.gut); const bad = JSON.stringify(S).match(/null,"x"|NaN/); assert.ok(!bad); for (const k of ['energy', 'chef', 'family', 'schicht']) assert.ok(S[k] >= 0 && S[k] <= 100, k); assert.ok(!/undefined/.test(S.result.why)); }
  const r = bot.run(60); if (!(r.meetingfan.win < r.gut.win)) console.log('WARNUNG: meetingfan nicht schwächer als gut (n=60)');
});
