  const D = sim.newGame(8); clearDay(D); D.pending = { id: 'tesla', t: 0 }; sim.choose(D, 'abwimmeln'); assert.strictEqual(sim.elonHeute(D), 1); toDay(D, 2); assert.strictEqual(sim.elonHeute(D), 0, 'neuer Tag');
