t('v0.6 Schichtübergabe: Wartezeit sichtbar, Ausschreibung nach ausgefallenem Dienstag am Mittwoch', () => { const S = sim.newGame(605); S.minute = 14 * 60 + 5; assert.strictEqual(sim.handoverWait(S, 'halle'), 15); assert.strictEqual(sim.handoverWait(S, 'buero'), 0); S.minute = 14 * 60 + 20; assert.strictEqual(sim.handoverWait(S, 'halle'), 0);
  const B = sim.newGame(606); toDay(B, 6); clearDay(B); B.minute = SC.DAY_END; B.burnout = true; sim.endDay(B); assert.strictEqual(sim.weekday(B), 1, 'Dienstag fällt aus'); if (B.phase !== 'ende') { sim.startDay(B); assert.strictEqual(sim.weekday(B), 2); assert.ok(B.auktion && B.auktion.week === sim.week(B), 'Ausschreibung am Mittwoch'); assert.strictEqual(B.auktion.closeDay, B.day); B.minute = 14 * 60 + 59; assert.ok(sim.auktionOpen(B)); B.minute = 15 * 60; assert.ok(!sim.auktionOpen(B)); } });
